steps.action:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "exclude_archived=true" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data.get('channels', []):
        print(ch['id'], ch['name'])
else:
    print('Error:', data.get('error'))
"

curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -d "channel=C_INC&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data.get('messages', []):
        print(msg['ts'], msg.get('text', '')[:100])
else:
    print('Error:', data.get('error'))
"
